typedef unsigned int size_t;

class singleton {};

struct sceGsDBuff
{
  char data[256];
};

class os_developer_options
{
public:
  enum flags_t
  {
    FLAG_NO_AUDIO
  };

  static os_developer_options* inst();
  bool is_flagged(flags_t);
};

struct movieplayer : public singleton
{
  void initHiRes(int width, int height);
  void clearGsMem(int r, int g, int b, int disp_width, int disp_height);

  bool hiRes;
  sceGsDBuff db;
};

void nglExit();
void nslShutdown();
void nvlMPEGSetMemoryAllocCallback(void* (*callback)(int, int));
void nvlMPEGSetMemoryFreeCallback(void (*callback)(void*));
void* KSMemAllocNVL(int size, int alignment);
void KSMemFree(void* memory);
int GetThreadId();
int ChangeThreadPriority(int thread_id, int priority);
void sceSifInitRpc(int mode);
void sceSifInitIopHeap();
bool _nvlLoadModule(char* module);
void debug_print(char* format, ...);
void sceGsResetPath();
void sceDmaReset(int channel);
void sceGsSetDefDBuff(
  sceGsDBuff* db,
  int pixel_format,
  int width,
  int height,
  int zbuffer,
  int zbuffer_format,
  int clear
);
void FlushCache(int mode);

enum
{
  NVLMPEG_PRIORITY = 9,
  SCE_GS_PSMCT32 = 0,
  SCE_GS_ZNOUSE = 1,
  SCE_GS_CLEAR = 1
};

static bool firstTime = true;

void movieplayer::initHiRes(int width, int height)
{
  bool res;

  hiRes = true;

  nglExit();
	if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
	{

		nslShutdown();
	}

  nvlMPEGSetMemoryAllocCallback((void *(*)(int, int))KSMemAllocNVL);
  nvlMPEGSetMemoryFreeCallback(KSMemFree);

  ChangeThreadPriority( GetThreadId(), NVLMPEG_PRIORITY );
  sceSifInitRpc( 0 );
  sceSifInitIopHeap();

	// We load these modules elsewhere too, so 
	// don't assert if it fails 

	if (firstTime)
	{
		// Don't load this if the sound already has
		if (os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
		{
			res = _nvlLoadModule("LIBSD.IRX" );
			if (!res)
				debug_print("Could not load libsd.irx from movieplayer.  Maybe its already loaded");
			res = _nvlLoadModule("SDRDRV.IRX" );
			if (!res)
				debug_print("Could not load sdrdrv.irx from movieplayer.  Maybe its already loaded");
			//assert( res );

		}

/*
		//assert( res );
		res = _nvlLoadModule("SDRDRV.IRX" );
		if (!res)
			debug_print("Could not load sdrdrv.irx from movieplayer.  Maybe its already loaded");
		//assert( res );*/
		firstTime =false;
	}

	/* should be loaded by the input manager
	res = _nvlLoadModule("sio2man.irx" );
	if (!res)
		debug_print("Could not load sio2man.irx from movieplayer.  Maybe its already loaded");
	*/
  //assert( res );

  sceGsResetPath();
  sceDmaReset( 1 );
#ifdef TV_PAL
  //sceGsResetGraph( 0, SCE_GS_INTERLACE, SCE_GS_PAL, SCE_GS_FRAME );
#else
  //sceGsResetGraph( 0, SCE_GS_INTERLACE, SCE_GS_NTSC, SCE_GS_FRAME );
#endif
  clearGsMem(0x00, 0x00, 0x00, width, height);
  sceGsSetDefDBuff( &db, SCE_GS_PSMCT32, width, (height/2), SCE_GS_ZNOUSE, 0, SCE_GS_CLEAR );
  FlushCache(0);
}
